def transform(grid):
    """Fill gaps between horizontal pairs of color-3 cells with color 2."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == 3 and row[c + 1] == 3:
                out[r][c] = 2
    return out

